  // left hairline stem
  "M41 32 L46 32 L46 178 L41 178 Z",
  // heavy left diagonal, slight concave belly
  "M44 30 L71 30 C84 70 98 112 112 150 L102 183 C88 130 64 76 44 30 Z",
