  "M100 183 L104 183 C122 132 140 82 159 32 L154 32 C136 82 118 132 100 183 Z",
  // heavy right stem
  "M150 30 L175 30 L175 178 L150 178 Z",
  // bracketed serifs
  "M26 27 L73 27 C70 29 69 31 70 33 L30 33 C28 31 27 29 26 27 Z",
  "M145 27 L191 27 C189 29 188 31 186 33 L150 33 C148 31 147 29 145 27 Z",
  "M27 176 L60 176 C58 178 58 180 60 182 L27 182 C29 180 29 178 27 176 Z",
