/** A calligraphic swash leaving the left foot. */
export const M_SWASH = "M29 179 C14 180 6 170 12 161 C16 155 24 156 25 162";

export const MGlyph: React.FC<{ fill: string; transform?: string; swash?: boolean; stroke?: string }> = ({
  fill,
  transform,
  swash = true,
  stroke,
}) => (
  <g transform={transform}>
    {M_GLYPH.map((d, i) => (
      <path key={i} d={d} fill={fill} />
    ))}
    {swash ? (
      <path d={M_SWASH} fill="none" stroke={stroke ?? fill} strokeWidth={3} strokeLinecap="round" />
    ) : null}
  </g>
);

/**
 * The couple's monogram: an interlaced R and N (Rishabh & Nandita) in high-contrast Cormorant,
 * the N set a touch lower so the two letters lock together. Drawn inside a 200×200 box.
 */
export const RNGlyph: React.FC<{ fill: string; transform?: string; stroke?: string; strokeWidth?: number }> = ({ fill, transform, stroke, strokeWidth = 0 }) => (
  <g transform={transform} fontFamily="'Cormorant Garamond', Georgia, serif" fontWeight={600} fill={fill} stroke={stroke} strokeWidth={strokeWidth}>
    <text x={72} y={150} fontSize={150} textAnchor="middle">R</text>
    <text x={132} y={168} fontSize={150} textAnchor="middle">N</text>
    <path d="M100 172 L106 180 L100 188 L94 180 Z" stroke="none" />
  </g>
);

// Arch geometry (viewBox 240×320). Outer ogee arch → apex at (120, 40).
const OUTER =
  "M22 304 L22 152 C22 98 70 76 101 60 C112 54 118 47 120 38 C122 47 128 54 139 60 C170 76 218 98 218 152 L218 304 Z";

const innerSide = (mirror: boolean): Pt[] => {
  const m = (p: Pt): Pt => (mirror ? [240 - p[0], p[1]] : p);
  // Two cubic segments per side, springing point → apex.
  const segA: [Pt, Pt, Pt, Pt] = [m([38, 156]), m([38, 110]), m([78, 92]), m([104, 76])];
  const segB: [Pt, Pt, Pt, Pt] = [m([104, 76]), m([113, 70]), m([118, 63]), m([120, 56])];
  const pts: Pt[] = [];
  for (let i = 0; i <= 5; i++) pts.push(cubicPoint(...segA, i / 5));
  for (let i = 1; i <= 2; i++) pts.push(cubicPoint(...segB, i / 2));
  return pts;
};

/**
 * Primary monogram: gold M inside a cusped jharokha arch with a lotus finial.
 * `draw` 0→1 reveals the arch line-work; `sweep` 0→1 moves a foil highlight across.
 */
export const Monogram: React.FC<{
  size?: number;
  draw?: number;
  sweep?: number;
  showArch?: boolean;
  style?: React.CSSProperties;
}> = ({ size = 240, draw = 1, sweep = 0.35, showArch = true, style }) => {
  const cusps = useMemo(() => {
    const left = innerSide(false);
    const right = innerSide(true);
    return { left: cuspedPath(left, 1), right: cuspedPath(right, 0) };
  }, []);
  const dash = 1400;
  const id = `mono-sweep-${Math.round(sweep * 1000)}`;
  const sx = -1 + sweep * 2.4;

  return (
    <svg width={size} height={(size * 320) / 240} viewBox="0 0 240 320" style={style}>
      <defs>
        <linearGradient id={id} x1={sx} y1={sx * 0.4} x2={sx + 1} y2={sx * 0.4 + 0.6}>
          <stop offset="0" stopColor="#7C5C29" />
          <stop offset="0.35" stopColor="#B48A45" />
          <stop offset="0.5" stopColor="#F6E7BF" />
          <stop offset="0.65" stopColor="#B48A45" />
          <stop offset="1" stopColor="#7C5C29" />
        </linearGradient>
      </defs>
      {showArch ? (
        <g
          fill="none"
          stroke="url(#foil)"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={dash}
          strokeDashoffset={dash * (1 - draw)}
        >
          <path d={OUTER} strokeWidth={2.4} />
          <path d={cusps.left} strokeWidth={1.4} />
          <path d={cusps.right} strokeWidth={1.4} />
          <path d="M38 156 L38 296 L202 296 L202 156" strokeWidth={1.4} />
          {/* plinth */}
          <path d="M14 304 L226 304" strokeWidth={1.6} />
          <path d="M30 312 L210 312" strokeWidth={1} />
        </g>
      ) : null}
      {showArch ? (
        <g opacity={draw}>
          {/* lotus finial */}
          <g fill="url(#foil-v)">
            <path d="M120 6 C127 15 127 26 120 33 C113 26 113 15 120 6 Z" />
            <path d="M120 33 C112 30 104 22 103 13 C110 16 117 23 120 33 Z" />
            <path d="M120 33 C128 30 136 22 137 13 C130 16 123 23 120 33 Z" />
          </g>
          {/* bead row on the plinth */}
          {new Array(9).fill(0).map((_, i) => (
            <circle key={i} cx={56 + i * 16} cy={308} r={1.6} fill="#B48A45" />
          ))}
        </g>
      ) : null}
      <RNGlyph fill={`url(#${id})`} transform="translate(56 132) scale(0.64)" />
    </svg>
  );
};
